1847	// a 1-based compensation attempt number. The input snapshot was captured via
1848	// copyInputWithFormDefaults and is copied again through it per attempt, so
1849	// the success-moment form defaults — including ones attached to a Date —
1850	// reach every attempt while remaining detached from it: mutating them, the
1851	// Date or a created parent on one failed attempt cannot touch the snapshot,
1852	// the run context, a later attempt, another run, or the stored success
1853	// output.
1854	async function runCompensation(entry, implementation, records) {
1855	  const { nodeId, binding, snapshot } = entry;
1856	  return runWithRetries({
1857	    retry: binding.compensation.retry,
1858	    prepareArgs: attempt => [
1859	      copyInputWithFormDefaults(snapshot.input), structuredClone(snapshot.output),
1860	      structuredClone(snapshot.result), nodeId, attempt,
1861	    ],
1862	    invoke: implementation,
1863	    createRecord: attempt => ({
1864	      nodeId, operation: binding.compensation.name, attempt,
1865	      ok: false, error: null, nextDelayMs: 0, result: null,
1866	    }),
1867	    copyFailureMessages: {
1868	      uncloneable: `compensation "${binding.compensation.name}" returned a value that cannot be structured-cloned`,
1869	      sharedMemory: `compensation "${binding.compensation.name}" returned a value that contains shared memory (SharedArrayBuffer or a typed array/DataView backed by one); independent copies cannot be guaranteed, so this return value is not supported`,
1870	    },
1871	    collect: record => records.push(record),
1872	    onSuccess: (record, returned) => { record.result = returned; },
1873	  });
1874	}
1875	
1876	// Undoes successful compensable business actions, most recent first, waiting
1877	// for each compensation to finish before starting the next. A compensation
1878	// that exhausts its retries is recorded as failed but earlier (still-pending)
1879	// actions are compensated regardless; neither the failed compensation nor the
1880	// original business operation is re-run. Compensating a node removes it from
1881	// the pending list exactly once — retried-then-succeeded actions and shared
1882	// join nodes were only recorded once to begin with.
1883	async function compensateRun(state, operations) {
1884	  const records = [];
1885	  let failed = false;
1886	  while (state.compensable.length > 0) {
1887	    const entry = state.compensable.pop();
1888	    const outcome = await runCompensation(entry, operations[entry.binding.compensation.name], records);
1889	    if (!outcome.ok) failed = true;
1890	  }
1891	  return { status: failed ? 'failed' : 'completed', attempts: records };
1892	}
1893	
1894	// Scheduling state shared by the synchronous and asynchronous execution
1895	// loops: activation, completion, dependency gating and the recorded end
1896	// result all behave identically; only business-action handling differs.
1897	//
1898	// The caller input is received — cloned and checked for retained shared
1899	// memory — here, the single point every entry passes through before any node
1900	// can run. Both entries call this after the definition, cancellation-option
1901	// and operation-registration checks but (for the asynchronous entry) before
1902	// the already-aborted-at-start short-circuit, so a shared-memory input is
1903	// rejected with a TypeError even when the signal has already fired.
1904	// `formRules`, `conditionRules`, `actionBindings` and `dependencies` are the
1905	// per-form compiled-rules map, the per-condition compiled-tree map, the
1906	// per-action compiled-binding map and the per-node dependency map produced by
1907	// the validation pass THIS run started through. They are captured here —
1908	// before the first suspension point — as part of the run state, so a form,
1909	// condition, business action or dependency gate that executes only after a
1910	// business-operation wait keeps using exactly the rules, expression, action
1911	// configuration and dependency relations that start-time validation
1912	// accepted: the operation actually invoked, its attempt count and waits,
1913	// whether a compensation runs under which name and retry settings, and which
1914	// nodes a node must wait for — including a dependency on a node the run
1915	// never activates, which still holds the gate until the run ends blocked. A
1916	// later validateWorkflow or a new run over the same node objects builds its
1917	// own maps and cannot reach these — even one that fails partway through,
1918	// since a rejected pass never publishes its maps at all. The compiled form
1919	// entries hold only primitives (field types restrict defaults to primitives)
1920	// and freshly built segment arrays; the compiled condition trees hold only
1921	// primitives, pre-resolved output-reference node ids and freshly built
1922	// segment arrays; the compiled bindings hold only the operation name strings
1923	// and fresh retry/compensation objects compileAction built; the dependency
1924	// lists are fresh arrays of id strings normalizeDependencies built — so all
1925	// four snapshots are already independent of the caller's definition. The
1926	// branch destinations (then/else/next) are deliberately not snapshotted
1927	// here: only the condition *expression*, the action configuration and the
1928	// dependency relations are pinned to the run's start, matching the
1929	// form-rules rule.
1930	function createRunState(nodes, workflow, input, formRules, conditionRules, actionBindings, dependencies) {
1931	  const declarationOrder = [...nodes.values()];
1932	  const declarationIndex = new Map(declarationOrder.map((node, index) => [node.id, index]));
1933	  return {
1934	    trace: [],
1935	    actionAttempts: [],
1936	    context: { input: cloneRunInput(input), output: {} },
1937	    formRules,
1938	    conditionRules,
1939	    actionBindings,
1940	    dependencies,
1941	    declarationOrder,
1942	    declarationIndex,
1943	    activated: new Set([workflow.entry]),
1944	    completed: new Set(),
1945	    endReached: false,
1946	    endResult: null,
1947	    // Successful business actions that declared a compensation, in the order
1948	    // they succeeded. Each entry keeps independent snapshots captured at the
1949	    // action's own success moment.
1950	    compensable: [],
1951	  };
1952	}
1953	
1954	function pickReadyNode(state) {
1955	  return state.declarationOrder.find(node =>
1956	    state.activated.has(node.id) && !state.completed.has(node.id)
1957	    && state.dependencies.get(node).every(dependency => state.completed.has(dependency)));
1958	}
1959	
1960	function blockedResult(state) {
1961	  const waiting = state.declarationOrder.filter(node =>
1962	    state.activated.has(node.id) && !state.completed.has(node.id));
1963	  if (waiting.length === 0) return null;
1964	  return waiting.map(node => ({
1965	    nodeId: node.id,
1966	    missingDependencies: state.dependencies.get(node)
1967	      .filter(dependency => !state.completed.has(dependency))
1968	      .sort((a, b) => state.declarationIndex.get(a) - state.declarationIndex.get(b)),
1969	  }));
1970	}
1971	
1972	// One shared scheduling step for the synchronous and asynchronous entries.
1973	// pickReadyNode already encodes activation plus dependency gating; this adds
1974	// the rules the two entries used to duplicate:
1975	// - a ready node is recorded in the trace the moment it enters execution, so
1976	//   waiting and never-activated nodes never appear in trace or output;
1977	// - an end node records its result and completes, but never stops the other
1978	//   activated branches — the caller simply loops again;
1979	// - with no ready node left, activated-but-waiting nodes classify the run as
1980	//   "blocked", a visited end node as "completed", and anything else is a
1981	//   structural cycle (validation rejects those before execution).
1982	// The terminal kinds are classifications only: each entry keeps building its
1983	// own result shape (the asynchronous one adds attempt and compensation
1984	// fields) so the public return values are unchanged.
1985	function advanceSchedule(state) {
1986	  const ready = pickReadyNode(state);
1987	  if (!ready) {
1988	    const waiting = blockedResult(state);
1989	    if (waiting) return { kind: 'blocked', waiting };
1990	    if (state.endReached) return { kind: 'completed' };
1991	    throw new Error('workflow did not terminate; a cycle is present');
1992	  }
1993	  state.trace.push({ nodeId: ready.id, type: ready.type });
1994	  if (ready.type === 'end') {
1995	    // Reaching an end node records the result but never stops other
1996	    // activated branches; the run completes once nothing can still run.
1997	    // Produce the independent snapshot at THIS end node's own execution
1998	    // moment from the value actually read now: later mutation of the
1999	    // definition's result (during a wait on another activated branch), of
2000	    // another run's result, or of the returned value cannot reach back
2001	    // here. Validation only proves the result was cloneable — and free of
2002	    // retained shared memory — as it was then; an enumerable getter may
2003	    // answer differently on this, its only execution-time read, and a
2004	    // preceding business operation may have replaced ordinary buffers with
2005	    // shared ones (or vice versa). The success is therefore recorded only
2006	    // if this read's clone is independently copyable. captureEndResult
2007	    // throws the end-result error (uncloneable, or retained shared memory)
2008	    // here: the synchronous entry propagates it and the asynchronous
2009	    // entry's Promise rejects with it — never a "completed" result, never
2010	    // an action_failed (no retry budget is spent) and no compensation runs.
2011	    // An unset or null result stays null; 0, false and "" pass through.
2012	    // Capture first: if the value read now cannot be independently copied,
2013	    // the throw leaves no partially-recorded end behind (the whole run is
2014	    // rejected, sync throw / async rejection, before endReached is set).
2015	    const result = captureEndResult(ready);
2016	    state.endReached = true;
2017	    state.endResult = result;
2018	    state.completed.add(ready.id);
2019	    return { kind: 'end' };
2020	  }
2021	  return { kind: 'run', node: ready };
2022	}
2023	
2024	// Applies a ready non-action node, mutating activation/completion state.
2025	// Returns an early-termination result (invalid_input / invalid_condition)
2026	// or null when execution should continue.
2027	function applyRegularNode(node, state) {
2028	  if (node.type === 'action') {
2029	    // Snapshot the legacy message at this action's own execution moment via
2030	    // the shared configured-value rule (readConfiguredCopy): the saved output
2031	    // is this run's independent deep copy, so editing nested fields, adding or
2032	    // deleting properties, or changing array members of the returned output
2033	    // never reaches the definition, another run, or an output this action
2034	    // recorded while another activated branch is still waiting.
2035	    // Validation only proved the message was safe as it was then — an
2036	    // enumerable getter may answer differently on this, its only
2037	    // execution-time read, and a preceding business operation may have
2038	    // replaced ordinary buffers with shared ones (or vice versa) — so the
2039	    // rule re-checks the value actually read now and throws the action-node
2040	    // error (uncloneable, or retained shared memory) when this run's copy
2041	    // cannot be independent. That throw is not a run status: the synchronous
2042	    // entry propagates it and the asynchronous entry's Promise rejects with
2043	    // it — never an action_failed, no retry budget is spent, no compensation
2044	    // runs, no output is recorded for this node and no later node executes.
2045	    // An unset, undefined or null message defaults to action:<node id>; "", 0
2046	    // and false pass through untouched.
2047	    setNodeOutput(
2048	      state.context.output,
2049	      node.id,
2050	      readConfiguredCopy(node, 'message', ACTION_MESSAGE_COPY_ERRORS, `action:${node.id}`),
2051	    );
2052	  }
2053	  if (node.type === 'form') {
2054	    const compiled = state.formRules.get(node);
2055	    if (compiled) {
2056	      const formResult = processForm(node, state.context.input, compiled);
2057	      if (!formResult.ok) {
2058	        return { status: 'invalid_input', context: state.context, trace: state.trace, errors: formResult.errors };
2059	      }
2060	    }
2061	  }
2062	  if (node.type === 'condition') {
2063	    // Evaluate the whole condition tree this run captured from the validation
2064	    // pass at its own start. A revalidation of the same definition while this
2065	    // run is parked on a business operation compiles a fresh tree into a
2066	    // different map and cannot reach this one, so changing the comparison
2067	    // constant, an input field path or an action-output reference — including
2068	    // inside nested all/any/not children — never changes the branch a waiting
2069	    // run has not chosen yet. The tree is pinned, not its result: evaluation
2070	    // still reads this run's current input and the successful action outputs
2071	    // saved so far, compounds still short-circuit in this tree's order, and
2072	    // an unconvertible numeric comparison is still invalid_condition at the
2073	    // position this run's expression gives it.
2074	    const outcome = runCondition(state.conditionRules.get(node), state.context.input, state.context.output, node.id);
2075	    if (!outcome.ok) {
2076	      return { status: 'invalid_condition', context: state.context, trace: state.trace, error: outcome.error };
2077	    }
2078	    state.activated.add(outcome.value ? node.then : node.else);
2079	  } else {
2080	    for (const target of successorTargets.get(node)) state.activated.add(target);
2081	  }
2082	  state.completed.add(node.id);
2083	  return null;
2084	}
2085	
2086	// Verifies, before a single node can run, that every business operation and
2087	// every compensation operation in the definition has a function registered —
2088	// including actions on untaken branches and entry-unreachable nodes.
2089	function resolveImplementation(operations, name, nodeId, kind) {
2090	  if (!isUsableObject(operations)
2091	    || !Object.hasOwn(operations, name)
2092	    || typeof operations[name] !== 'function') {
2093	    throw new Error(`action node ${nodeId}: ${kind} operation "${name}" has no function implementation; pass it to executeWorkflowAsync`);
2094	  }
2095	  return operations[name];
2096	}
2097	
2098	function verifyOperations(nodes, operations, actionBindings) {
2099	  for (const node of nodes.values()) {
2100	    const binding = actionBindings.get(node);
2101	    if (binding && binding.name !== null) {
2102	      resolveImplementation(operations, binding.name, node.id, 'business');
2103	    }
2104	    if (binding && binding.compensation !== null) {
2105	      resolveImplementation(operations, binding.compensation.name, node.id, 'compensation');
2106	    }
2107	  }
2108	}
2109	
2110	// The optional fourth argument of executeWorkflowAsync carries an
2111	// AbortSignal as `{ signal }`. Omitting it — or passing undefined, or an
2112	// options object without a signal — keeps the previous behavior; anything
2113	// else is a caller error reported before a single node executes.
2114	function resolveRunSignal(options) {
2115	  if (options === undefined) return null;
2116	  if (!isUsableObject(options)) {
2117	    throw new TypeError('executeWorkflowAsync options must be an object with an optional "signal" AbortSignal');
2118	  }
2119	  if (!Object.hasOwn(options, 'signal') || options.signal === undefined) return null;
2120	  const { signal } = options;
2121	  if (signal instanceof AbortSignal) return signal;
2122	  throw new TypeError('executeWorkflowAsync options.signal must be an AbortSignal');
2123	}
2124	
2125	export function executeWorkflow(workflow, input = {}) {
2126	  const { nodes, formRules, conditionRules, actionBindings, dependencies } = compileWorkflow(workflow);
2127	  // Business operations are asynchronous: the synchronous entry must refuse
2128	  // a workflow that names any before a single node executes.
2129	  for (const node of nodes.values()) {
2130	    const binding = actionBindings.get(node);
2131	    if (binding && binding.name !== null) {
2132	      throw new Error(`action node ${node.id} names business operation "${binding.name}", which must run asynchronously; use executeWorkflowAsync instead of executeWorkflow`);
2133	    }
2134	  }
2135	
2136	  const state = createRunState(nodes, workflow, input, formRules, conditionRules, actionBindings, dependencies);
2137	
2138	  for (;;) {
2139	    const step = advanceSchedule(state);
2140	
2141	    if (step.kind === 'blocked') {
2142	      return { status: 'blocked', context: state.context, trace: state.trace, blockedNodes: step.waiting };
2143	    }
2144	    if (step.kind === 'completed') {
2145	      return { status: 'completed', result: state.endResult, context: state.context, trace: state.trace };
2146	    }
2147	    if (step.kind === 'end') continue;
2148	
2149	    const early = applyRegularNode(step.node, state);
2150	    if (early) return early;
2151	  }
2152	}
2153	
2154	// Attaches compensation results to a failed run. Successful outputs and the
2155	// original terminal status stay untouched; compensation records live on
2156	// their own fields, never in the regular node trace.
2157	async function withCompensation(result, state, operations) {
2158	  const outcome = await compensateRun(state, operations);
2159	  result.compensationStatus = outcome.attempts.length === 0 ? 'not_needed' : outcome.status;
2160	  result.compensationAttempts = outcome.attempts;
2161	  return result;
2162	}
2163	
2164	// The cancelled terminal shape: the run stops where it is, keeps the
2165	// context, trace and attempt records produced so far, and never carries a
2166	// success result. Compensation for already-succeeded actions is attached by
2167	// withCompensation under the usual rules.
2168	function cancelledResult(state) {
2169	  return {
2170	    status: 'cancelled',
2171	    context: state.context,
2172	    trace: state.trace,
2173	    actionAttempts: state.actionAttempts,
2174	  };
2175	}
2176	
2177	export async function executeWorkflowAsync(workflow, input = {}, operations = {}, options = undefined) {
2178	  const signal = resolveRunSignal(options);
2179	  const { nodes, formRules, conditionRules, actionBindings, dependencies } = compileWorkflow(workflow);
2180	  verifyOperations(nodes, operations, actionBindings);
2181	
2182	  const state = createRunState(nodes, workflow, input, formRules, conditionRules, actionBindings, dependencies);
2183	
2184	  // A signal that is already aborted stops the run before the first node —
2185	  // but only after the definition and the operation registrations above have
2186	  // been checked. Nothing executes and nothing is compensated.
2187	  if (signal && signal.aborted) {
2188	    return withCompensation(cancelledResult(state), state, operations);
2189	  }
2190	
2191	  for (;;) {
2192	    // Once the signal fires, no new regular node runs and no new business
2193	    // action attempt starts; the run ends cancelled with whatever state it
2194	    // reached, even if an end node was already visited on another branch.
2195	    if (signal && signal.aborted) {
2196	      return withCompensation(cancelledResult(state), state, operations);
2197	    }
2198	
2199	    const step = advanceSchedule(state);
2200	
2201	    if (step.kind === 'blocked') {
2202	      // Unmet dependencies end the run; successful compensable actions are
2203	      // rolled back even though an end node may already have been reached.
2204	      return withCompensation({
2205	        status: 'blocked', context: state.context, trace: state.trace,
2206	        blockedNodes: step.waiting, actionAttempts: state.actionAttempts,
2207	      }, state, operations);
2208	    }
2209	    if (step.kind === 'completed') {
2210	      // A completed run never invokes compensation.
2211	      return {
2212	        status: 'completed', result: state.endResult, context: state.context,
2213	        trace: state.trace, actionAttempts: state.actionAttempts,
2214	        compensationStatus: 'not_needed', compensationAttempts: [],
2215	      };
2216	    }
2217	    if (step.kind === 'end') continue;
2218	
2219	    const ready = step.node;
2220	    if (ready.type === 'action') {
2221	      // The binding this run captured at its own start: a revalidation of the
2222	      // same node object while this run was parked compiled a fresh binding
2223	      // into a different map and cannot reach this one, so the operation
2224	      // invoked, the retry budget and the compensation configuration are
2225	      // exactly the ones this run's start-time validation accepted.
2226	      const binding = state.actionBindings.get(ready);
2227	      if (binding.name !== null) {
2228	        // Nodes execute one at a time in declaration order; awaiting here
2229	        // never lets another node jump ahead.
2230	        const actionResult = await runBusinessAction(
2231	          ready, binding, operations[binding.name], state.context, state.actionAttempts, signal);
2232	        if (!actionResult.ok) {
2233	          if (actionResult.cancelled) {
2234	            // Cancelled while the action was in flight or waiting to retry:
2235	            // the attempt records produced so far stay as they are.
2236	            return withCompensation(cancelledResult(state), state, operations);
2237	          }
2238	          // Retries are exhausted: stop immediately with prior input/output
2239	          // preserved, no output for this node and no successors activated —
2240	          // even if an end node was already reached — then compensate every
2241	          // earlier successful action that asked for it.
2242	          return withCompensation({
2243	            status: 'action_failed', nodeId: ready.id, attempts: binding.retry.attempts,
2244	            error: actionResult.error, context: state.context, trace: state.trace,
2245	            actionAttempts: state.actionAttempts,
2246	          }, state, operations);
2247	        }
2248	        // Capture the compensation snapshots from the state before the new
2249	        // output key lands: the action's own return value is handed to the
2250	        // compensation separately as its third argument. The input snapshot
2251	        // goes through copyInputWithFormDefaults, so it freezes exactly the
2252	        // defaults already effective at this action's success moment —
2253	        // including ones a form attached to a Date — while fields a later
2254	        // form adds to the live run input can never enter it.
2255	        const compensationSnapshot = binding.compensation === null ? null : {
2256	          input: copyInputWithFormDefaults(state.context.input),
2257	          output: structuredClone(state.context.output),
2258	          result: structuredClone(actionResult.value),
2259	        };
2260	        setNodeOutput(state.context.output, ready.id, actionResult.value);
2261	        if (compensationSnapshot) {
2262	          // Each node completes at most once, so retried-then-successful
2263	          // actions and shared join nodes are scheduled for compensation
2264	          // exactly once.
2265	          state.compensable.push({ nodeId: ready.id, binding, snapshot: compensationSnapshot });
2266	        }
2267	        for (const target of successorTargets.get(ready)) state.activated.add(target);
2268	        state.completed.add(ready.id);
2269	        continue;
2270	      }
2271	    }
2272	
2273	    const early = applyRegularNode(ready, state);
2274	    if (early) {
2275	      early.actionAttempts = state.actionAttempts;
2276	      // A failed form (invalid_input) or failed condition evaluation
2277	      // (invalid_condition) ends normal execution and triggers compensation
2278	      // of the successful business actions that ran earlier.
2279	      return withCompensation(early, state, operations);
2280	    }
2281	  }
2282	}
